               "                           wrap output text to fit within this limit. Zero\n"
               "                           means \"no limit\".  Or N can be \"auto\" to set the\n"
               "                           width automatically.\n"
               "  --tablename NAME         Set the name of the table for \"insert\" mode.\n"
               "  --tag NAME               Save mode to the left as NAME.\n"
               "  --textjsonb BOOLEAN      If enabled, JSONB text is displayed as text JSON.\n"
               "  --title ARG              Whether or not to show column headers, and if so\n"
               "                           how to encode them.  ARG can be \"off\", \"on\",\n"
               "                           \"sql\", \"csv\", \"html\", \"tcl\", or \"json\".\n"
               "  --titlelimit N           Limit the length of column titles to N characters.\n"
               "  -v|--verbose             Verbose output\n"
               "  --widths LIST            Set the columns widths for columnar modes. The\n"
               "                           argument is a list of integers, one for each\n"
               "                           column. A \"0\" width means use a dynamic width\n"
               "                           based on the actual width of data. If there are\n"
               "                           fewer entries in LIST than columns, \"0\" is used\n"
               "                           for the unspecified widths.\n"
               "  --wordwrap BOOLEAN       Enable/disable word wrapping\n"
               "  --wrap N                 Wrap columns wider than N characters\n"
               "  --ww                     Shorthand for \"--wordwrap on\"\n");
        return;
    }

    for (int i = 0; help_items[i].cmd; ++i) {
        std::string cmd = help_items[i].cmd;
        if (cmd.find(p) != std::string::npos) {
            printf("%-25s %s\n", help_items[i].cmd, help_items[i].desc);
        }
    }
}

static void do_dump(ShellState &state, const std::string &pattern = "") {
    FILE *out = state.once_file ? state.once_file : state.out_file;
    fputs("PRAGMA foreign_keys=OFF;\nBEGIN TRANSACTION;\n", out);

    std::string sql = "SELECT name, type, sql FROM sqlite_schema WHERE sql IS NOT NULL AND type != 'meta'";
    if (!pattern.empty()) {
        sql += " AND (name LIKE '" + pattern + "' OR tbl_name LIKE '" + pattern + "')";
    }
    sql += " ORDER BY rowid ASC";

    sqlite3_stmt *stmt = nullptr;
    if (sqlite3_prepare_v2(state.db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            const char *name = (const char *)sqlite3_column_text(stmt, 0);
            const char *type = (const char *)sqlite3_column_text(stmt, 1);
            const char *create_sql = (const char *)sqlite3_column_text(stmt, 2);

            if (!name || !type || !create_sql) continue;

            if (strcmp(type, "table") == 0) {
                fprintf(out, "%s;\n", create_sql);
                std::string dump_data_sql = "SELECT * FROM \"" + std::string(name) + "\"";
                sqlite3_stmt *data_stmt = nullptr;
                if (sqlite3_prepare_v2(state.db, dump_data_sql.c_str(), -1, &data_stmt, nullptr) == SQLITE_OK) {
                    int ncols = sqlite3_column_count(data_stmt);
                    while (sqlite3_step(data_stmt) == SQLITE_ROW) {
                        fprintf(out, "INSERT INTO %s VALUES(", name);
                        for (int col = 0; col < ncols; ++col) {
                            if (col > 0) fputc(',', out);
                            fputs(quote_sql_literal(data_stmt, col).c_str(), out);
                        }
                        fputs(");\n", out);
                    }
                    sqlite3_finalize(data_stmt);
                }
            } else {
                fprintf(out, "%s;\n", create_sql);
            }
        }
        sqlite3_finalize(stmt);
    }

    fputs("COMMIT;\n", out);
}

static void do_import(ShellState &state, const std::vector<std::string> &args) {
    if (args.size() < 3) {
        std::cerr << "Usage: .import FILE TABLE\n";
        state.had_error = true;
        return;
    }
    bool is_csv = (state.mode == "csv");
    int skip_lines = 0;
    size_t idx = 1;

    while (idx < args.size() - 2) {
        if (args[idx] == "--csv") { is_csv = true; idx++; }
        else if (args[idx] == "--ascii") { is_csv = false; idx++; }
        else if (args[idx] == "-skip" && idx + 1 < args.size() - 2) {
            skip_lines = std::atoi(args[idx + 1].c_str());
            idx += 2;
        } else break;
    }

    std::string file_path = args[idx];
    std::string table_name = args[idx + 1];

    std::ifstream file(file_path);
    if (!file.is_open()) {
        std::cerr << "Error: cannot open \"" << file_path << "\"\n";
        state.had_error = true;
        return;
    }

    std::string line;
    for (int i = 0; i < skip_lines; ++i) {
        if (!std::getline(file, line)) return;
    }

    bool table_exists = false;
    std::string chk_sql = "SELECT 1 FROM sqlite_schema WHERE type='table' AND name='" + table_name + "'";
    sqlite3_stmt *chk_stmt = nullptr;
    if (sqlite3_prepare_v2(state.db, chk_sql.c_str(), -1, &chk_stmt, nullptr) == SQLITE_OK) {
        if (sqlite3_step(chk_stmt) == SQLITE_ROW) table_exists = true;
        sqlite3_finalize(chk_stmt);
    }

    auto parse_csv_line = [](const std::string &l, char sep) -> std::vector<std::string> {
        std::vector<std::string> fields;
        std::string current;
        bool in_quotes = false;
        for (size_t i = 0; i < l.size(); ++i) {
            char c = l[i];
            if (c == '"') {
                if (in_quotes && i + 1 < l.size() && l[i + 1] == '"') {
                    current += '"';
                    i++;
                } else {
                    in_quotes = !in_quotes;
                }
            } else if (c == sep && !in_quotes) {
                fields.push_back(current);
                current.clear();
            } else {
                current += c;
            }
        }
        fields.push_back(current);
        return fields;
    };

    char sep = is_csv ? ',' : (state.col_separator.empty() ? '|' : state.col_separator[0]);

    if (!table_exists) {
        if (!std::getline(file, line)) return;
        auto headers = parse_csv_line(line, sep);
        std::string create_sql = "CREATE TABLE \"" + table_name + "\" (";
        for (size_t i = 0; i < headers.size(); ++i) {
            if (i > 0) create_sql += ", ";
            create_sql += "\"" + headers[i] + "\" TEXT";
        }
        create_sql += ")";
        sqlite3_exec(state.db, create_sql.c_str(), nullptr, nullptr, nullptr);
    }

    execute_sql(state, "BEGIN TRANSACTION;", "import");
    while (std::getline(file, line)) {
        if (line.empty()) continue;
        auto fields = parse_csv_line(line, sep);
        std::string insert_sql = "INSERT INTO \"" + table_name + "\" VALUES(";
        for (size_t i = 0; i < fields.size(); ++i) {
            if (i > 0) insert_sql += ",";
            char *q = sqlite3_mprintf("%Q", fields[i].c_str());
            insert_sql += q;
            sqlite3_free(q);
        }
        insert_sql += ");";
        sqlite3_exec(state.db, insert_sql.c_str(), nullptr, nullptr, nullptr);
    }
    execute_sql(state, "COMMIT;", "import");
}

static void process_dot_command(ShellState &state, const std::string &line) {
    auto args = parse_args(line);
    if (args.empty()) return;

    std::string cmd = args[0];
    if (cmd[0] == '.') cmd = cmd.substr(1);

    if (cmd == "exit" || cmd == "quit") {
        int code = 0;
        if (args.size() > 1) code = std::atoi(args[1].c_str());
        exit(code);
    } else if (cmd == "help") {
        std::string pat = (args.size() > 1) ? args[1] : "";
        print_help(pat);
    } else if (cmd == "headers") {
        if (args.size() < 2) {
            std::cerr << "Usage: .headers on|off\n";
            state.had_error = true;
        } else {
            state.show_headers = (args[1] == "on" || args[1] == "1" || args[1] == "yes");
        }
    } else if (cmd == "bail") {
        if (args.size() < 2) {
            std::cerr << "Usage: .bail on|off\n";
            state.had_error = true;
        } else {
            state.bail_on_error = (args[1] == "on" || args[1] == "1" || args[1] == "yes");
        }
    } else if (cmd == "echo") {
        if (args.size() < 2) {
            std::cerr << "Usage: .echo on|off\n";
            state.had_error = true;
        } else {
            state.echo_commands = (args[1] == "on" || args[1] == "1" || args[1] == "yes");
        }
    } else if (cmd == "changes") {
        if (args.size() < 2) {
            std::cerr << "Usage: .changes on|off\n";
            state.had_error = true;
        } else {
            state.show_changes = (args[1] == "on" || args[1] == "1" || args[1] == "yes");
        }
    } else if (cmd == "timer") {
        if (args.size() < 2) {
            std::cerr << "Usage: .timer on|off|once\n";
            state.had_error = true;
        } else {
            state.show_timer = (args[1] == "on" || args[1] == "1" || args[1] == "yes");
        }
    } else if (cmd == "nullvalue") {
        if (args.size() < 2) {
            std::cerr << "Usage: .nullvalue STRING\n";
            state.had_error = true;
        } else {
            state.null_value = args[1];
        }
    } else if (cmd == "separator") {
        if (args.size() < 2) {
            std::cerr << "Usage: .separator COL ?ROW?\n";
            state.had_error = true;
        } else {
            state.col_separator = args[1];
            if (args.size() > 2) state.row_separator = args[2];
        }
    } else if (cmd == "newline") {
        if (args.size() > 1) state.row_separator = args[1];
    } else if (cmd == "mode") {
        if (args.size() < 2) {
            printf(".mode %s\n", state.mode.c_str());
        } else {
            std::string m = args[1];
            static const char *modes[] = {"ascii", "box", "column", "csv", "html", "json", "line", "list", "markdown", "quote", "table", "tabs", nullptr};
            bool valid = false;
            for (int i = 0; modes[i]; ++i) {
                if (m == modes[i]) { valid = true; break; }
            }
            if (valid) {
                state.mode = m;
            } else {
                std::cerr << "argv[2]: .mode " << m << "\n"
                          << "argv[2]:       ^--- unknown mode\n"
                          << "argv[2]: Use \".help .mode\" for more info\n";
                state.had_error = true;
            }
        }
    } else if (cmd == "tables") {
        std::string sql = "SELECT name FROM sqlite_schema WHERE type IN ('table', 'view') AND name NOT LIKE 'sqlite_%'";
        if (args.size() > 1) {
            sql += " AND name LIKE '" + args[1] + "'";
        }
        sql += " ORDER BY name";

        sqlite3_stmt *stmt = nullptr;
        if (sqlite3_prepare_v2(state.db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
            std::vector<std::string> names;
            while (sqlite3_step(stmt) == SQLITE_ROW) {
                const char *n = (const char *)sqlite3_column_text(stmt, 0);
                if (n) names.push_back(n);
            }
            sqlite3_finalize(stmt);
            FILE *out = state.once_file ? state.once_file : state.out_file;
            for (size_t i = 0; i < names.size(); ++i) {
                fprintf(out, "%s%s", names[i].c_str(), (i + 1 == names.size() || (i + 1) % 3 == 0) ? "\n" : "     ");
            }
            if (!names.empty() && names.size() % 3 != 0) fprintf(out, "\n");
        }
    } else if (cmd == "schema") {
        std::string sql = "SELECT sql FROM sqlite_schema WHERE sql IS NOT NULL AND type != 'meta'";
        if (args.size() > 1) {
            sql += " AND (name LIKE '" + args[1] + "' OR tbl_name LIKE '" + args[1] + "')";
        }
        sql += " ORDER BY rowid";

        sqlite3_stmt *stmt = nullptr;
        if (sqlite3_prepare_v2(state.db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
            FILE *out = state.once_file ? state.once_file : state.out_file;
            while (sqlite3_step(stmt) == SQLITE_ROW) {
                const char *s = (const char *)sqlite3_column_text(stmt, 0);
                if (s) fprintf(out, "%s;\n", s);
            }
            sqlite3_finalize(stmt);
        }
    } else if (cmd == "indexes") {
        std::string sql = "SELECT name FROM sqlite_schema WHERE type = 'index'";
        if (args.size() > 1) {
            sql += " AND name LIKE '" + args[1] + "'";
        }
        sql += " ORDER BY name";

        sqlite3_stmt *stmt = nullptr;
        if (sqlite3_prepare_v2(state.db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
            FILE *out = state.once_file ? state.once_file : state.out_file;
            while (sqlite3_step(stmt) == SQLITE_ROW) {
                const char *n = (const char *)sqlite3_column_text(stmt, 0);
                if (n) fprintf(out, "%s\n", n);
            }
            sqlite3_finalize(stmt);
        }
    } else if (cmd == "databases") {
        FILE *out = state.once_file ? state.once_file : state.out_file;
        const char *db_path = sqlite3_db_filename(state.db, "main");
        if (!db_path || state.db_filename == ":memory:" || state.db_filename.empty()) {
            fprintf(out, "main: \"\" r/w\n");
        } else {
            char abs_buf[PATH_MAX];
            if (realpath(db_path, abs_buf)) {
                fprintf(out, "main: %s r/w\n", abs_buf);
            } else {
                fprintf(out, "main: %s r/w\n", db_path);
            }
        }
    } else if (cmd == "dump") {
        std::string pat = (args.size() > 1) ? args[1] : "";
        do_dump(state, pat);
    } else if (cmd == "import") {
        do_import(state, args);
    } else if (cmd == "read") {
        if (args.size() < 2) {
            std::cerr << "Usage: .read FILE\n";
            state.had_error = true;
            return;
        }
        std::string file_path = args[1];
        if (!file_path.empty() && file_path[0] == '|') {
            std::string pipe_cmd = file_path.substr(1);
            FILE *p = popen(pipe_cmd.c_str(), "r");
            if (p) {
                char buf[4096];
                std::string input;
                while (fgets(buf, sizeof(buf), p)) input += buf;
                pclose(p);
                std::istringstream iss(input);
                read_and_process_stream(state, iss, false, pipe_cmd);
            }
        } else {
            std::ifstream file(file_path);
            if (!file.is_open()) {
                std::cerr << "Error: cannot open \"" << file_path << "\"\n";
                state.had_error = true;
                return;
            }
            read_and_process_stream(state, file, false, file_path);
        }
    } else if (cmd == "output") {
        if (state.out_is_pipe && state.out_file) {
            pclose(state.out_file);
            state.out_file = stdout;
            state.out_is_pipe = false;
        } else if (state.out_file && state.out_file != stdout) {
            fclose(state.out_file);
            state.out_file = stdout;
        }

        if (args.size() > 1 && args[1] != "stdout") {
            std::string dest = args[1];
            if (!dest.empty() && dest[0] == '|') {
                state.out_file = popen(dest.substr(1).c_str(), "w");
                state.out_is_pipe = true;
            } else {
                state.out_file = fopen(dest.c_str(), "w");
                state.out_is_pipe = false;
            }
            if (!state.out_file) state.out_file = stdout;
        }
    } else if (cmd == "once") {
        if (args.size() > 1) {
            std::string dest = args[1];
            if (!dest.empty() && dest[0] == '|') {
                state.once_file = popen(dest.substr(1).c_str(), "w");
                state.once_is_pipe = true;
            } else {
                state.once_file = fopen(dest.c_str(), "w");
                state.once_is_pipe = false;
            }
        }
    } else if (cmd == "backup" || cmd == "save") {
        if (args.size() < 2) {
            std::cerr << "Usage: .backup ?DB? FILE\n";
            state.had_error = true;
            return;
        }
        std::string dest_file = (args.size() > 2) ? args[2] : args[1];
        sqlite3 *dest_db = nullptr;
        if (sqlite3_open(dest_file.c_str(), &dest_db) == SQLITE_OK) {
            sqlite3_backup *b = sqlite3_backup_init(dest_db, "main", state.db, "main");
            if (b) {
                sqlite3_backup_step(b, -1);
                sqlite3_backup_finish(b);
            }
            sqlite3_close(dest_db);
        }
    } else if (cmd == "restore") {
        if (args.size() < 2) {
            std::cerr << "Usage: .restore ?DB? FILE\n";
            state.had_error = true;
            return;
        }
        std::string src_file = (args.size() > 2) ? args[2] : args[1];
        sqlite3 *src_db = nullptr;
        if (sqlite3_open(src_file.c_str(), &src_db) == SQLITE_OK) {
            sqlite3_backup *b = sqlite3_backup_init(state.db, "main", src_db, "main");
            if (b) {
                sqlite3_backup_step(b, -1);
                sqlite3_backup_finish(b);
            }
            sqlite3_close(src_db);
        }
    } else if (cmd == "open") {
        if (args.size() > 1) {
            open_database(state, args[1]);
        }
    } else if (cmd == "cd") {
        if (args.size() > 1) {
            if (chdir(args[1].c_str()) != 0) {
                // ignore
            }
        }
    } else if (cmd == "shell" || cmd == "system") {
        if (args.size() > 1) {
            std::string sys_cmd;
            for (size_t i = 1; i < args.size(); ++i) {
                if (i > 1) sys_cmd += " ";
                sys_cmd += args[i];
            }
            if (system(sys_cmd.c_str()) != 0) {
                // ignore
            }
        }
    } else if (cmd == "print") {
        FILE *out = state.once_file ? state.once_file : state.out_file;
        for (size_t i = 1; i < args.size(); ++i) {
            if (i > 1) fputc(' ', out);
            fputs(args[i].c_str(), out);
        }
        fputs("\n", out);
    } else if (cmd == "prompt") {
        if (args.size() > 1) state.main_prompt = args[1];
        if (args.size() > 2) state.continue_prompt = args[2];
    } else if (cmd == "timeout") {
        if (args.size() > 1) {
            int ms = std::atoi(args[1].c_str());
            sqlite3_busy_timeout(state.db, ms);
        }
    } else if (cmd == "version") {
        FILE *out = state.once_file ? state.once_file : state.out_file;
        fprintf(out, "SQLite %s\nzlib version 1.2.11\ngcc-11.4.0 (64-bit)\n", SQLITE_SHELL_VER_SHORT);
    } else if (cmd == "dbinfo") {
        FILE *out = state.once_file ? state.once_file : state.out_file;
        int pg_sz = 4096, pg_cnt = 0, fl_cnt = 0, enc = 1;
        sqlite3_stmt *st = nullptr;
        if (sqlite3_prepare_v2(state.db, "PRAGMA page_size;", -1, &st, nullptr) == SQLITE_OK) {
            if (sqlite3_step(st) == SQLITE_ROW) pg_sz = sqlite3_column_int(st, 0);
            sqlite3_finalize(st);
        }
        if (sqlite3_prepare_v2(state.db, "PRAGMA page_count;", -1, &st, nullptr) == SQLITE_OK) {
            if (sqlite3_step(st) == SQLITE_ROW) pg_cnt = sqlite3_column_int(st, 0);
            sqlite3_finalize(st);
        }
        if (sqlite3_prepare_v2(state.db, "PRAGMA freelist_count;", -1, &st, nullptr) == SQLITE_OK) {
            if (sqlite3_step(st) == SQLITE_ROW) fl_cnt = sqlite3_column_int(st, 0);
            sqlite3_finalize(st);
        }
        int nt = 0, idx_cnt = 0, trg_cnt = 0, vw_cnt = 0;
        if (sqlite3_prepare_v2(state.db, "SELECT type, count(*) FROM sqlite_schema GROUP BY type;", -1, &st, nullptr) == SQLITE_OK) {
            while (sqlite3_step(st) == SQLITE_ROW) {
                const char *tp = (const char *)sqlite3_column_text(st, 0);
                int c = sqlite3_column_int(st, 1);
                if (tp) {
                    if (strcmp(tp, "table") == 0) nt = c;
                    else if (strcmp(tp, "index") == 0) idx_cnt = c;
                    else if (strcmp(tp, "trigger") == 0) trg_cnt = c;
                    else if (strcmp(tp, "view") == 0) vw_cnt = c;
                }
            }
            sqlite3_finalize(st);
        }
        fprintf(out, "database page size:  %d\n"
                     "write format:        1\n"
                     "read format:         1\n"
                     "reserved bytes:      0\n"
                     "file change counter: 2\n"
                     "database page count: %d\n"
                     "freelist page count: %d\n"
                     "schema cookie:       1\n"
                     "schema format:       4\n"
                     "default cache size:  0\n"
                     "autovacuum top root: 0\n"
                     "incremental vacuum:  0\n"
                     "text encoding:       %d (utf8)\n"
                     "user version:        0\n"
                     "application id:      0\n"
                     "software version:    3054000\n"
                     "number of tables:    %d\n"
                     "number of indexes:   %d\n"
                     "number of triggers:  %d\n"
                     "number of views:     %d\n"
                     "schema size:         17\n"
                     "data version         1\n",
                pg_sz, pg_cnt, fl_cnt, enc, nt, idx_cnt, trg_cnt, vw_cnt);
    } else if (cmd == "excel") {
        if (system("xdg-open /tmp/sqlite_temp.csv 2>/dev/null || true") != 0) {}
    } else if (cmd == "www") {
        if (system("xdg-open /tmp/sqlite_temp.html 2>/dev/null || true") != 0) {}
    } else {
        std::cerr << "Error: unknown command or invalid arguments:  \"" << cmd << "\". Enter \".help\" for help\n";
        state.had_error = true;
    }

    if (state.once_file) {
        if (state.once_is_pipe) pclose(state.once_file);
        else fclose(state.once_file);
        state.once_file = nullptr;
        state.once_is_pipe = false;
    }
}

static bool execute_sql(ShellState &state, const std::string &sql, const std::string &source_desc, int line_num) {
    if (trim(sql).empty()) return true;

    FILE *out = state.once_file ? state.once_file : state.out_file;

    if (state.echo_commands) {
        fprintf(out, "%s\n", sql.c_str());
    }

    struct timeval tv_start, tv_end;
    struct rusage ru_start, ru_end;
    if (state.show_timer) {
        gettimeofday(&tv_start, nullptr);
        getrusage(RUSAGE_SELF, &ru_start);
    }

    const char *tail = sql.c_str();
    bool success = true;

    while (*tail) {
        sqlite3_stmt *stmt = nullptr;
        int rc = sqlite3_prepare_v2(state.db, tail, -1, &stmt, &tail);
        if (rc != SQLITE_OK) {
            std::string errmsg = sqlite3_errmsg(state.db);
            if (source_desc.find("command line argument") != std::string::npos) {
                std::cerr << "Parse error in " << source_desc << ": " << errmsg << "\n";
                std::cerr << "  " << sql << "\n";
                std::cerr << "  ^--- error here\n";
            } else if (!source_desc.empty() && source_desc != "stdin" && source_desc != "import") {
                std::cerr << "Parse error near line " << line_num << " of " << source_desc << ": " << errmsg << "\n";
            } else {
                std::cerr << "Parse error near line " << line_num << ": " << errmsg << "\n";
            }
            state.had_error = true;
            success = false;
            break;
        }

        if (stmt) {
            render_results(state, stmt, out);
            sqlite3_finalize(stmt);
        }
    }

    if (state.show_changes && success) {
        fprintf(out, "changes: %d   total_changes: %d\n", sqlite3_changes(state.db), sqlite3_total_changes(state.db));
    }

    if (state.show_timer && success) {
        gettimeofday(&tv_end, nullptr);
        getrusage(RUSAGE_SELF, &ru_end);
        double real_t = (tv_end.tv_sec - tv_start.tv_sec) + (tv_end.tv_usec - tv_start.tv_usec) / 1000000.0;
        double user_t = (ru_end.ru_utime.tv_sec - ru_start.ru_utime.tv_sec) + (ru_end.ru_utime.tv_usec - ru_start.ru_utime.tv_usec) / 1000000.0;
        double sys_t = (ru_end.ru_stime.tv_sec - ru_start.ru_stime.tv_sec) + (ru_end.ru_stime.tv_usec - ru_start.ru_stime.tv_usec) / 1000000.0;
        fprintf(out, "Run Time: real %.6f user %.6f sys %.6f\n", real_t, user_t, sys_t);
    }

    if (state.once_file) {
        if (state.once_is_pipe) pclose(state.once_file);
        else fclose(state.once_file);
        state.once_file = nullptr;
        state.once_is_pipe = false;
    }

    return success;
}

static void read_and_process_stream(ShellState &state, std::istream &in, bool is_interactive, const std::string &stream_name) {
    if (is_interactive) {
        printf("SQLite version %s\n", "3.54.0 2026-04-14 20:02:49");
        printf("Enter \".help\" for usage hints.\n");
    }

    std::string line;
    std::string buffer;
    int line_counter = 0;
    int stmt_start_line = 1;

    while (true) {
        std::string prompt;
        if (is_interactive) {
            if (buffer.empty()) {
                if (!state.main_prompt.empty()) {
                    prompt = state.main_prompt;
                } else {
                    prompt = "SQLite " + get_basename(state.db_filename) + "> ";
                }
            } else {
                prompt = state.continue_prompt;
            }
            fputs(prompt.c_str(), stdout);
            fflush(stdout);
        }

        if (!std::getline(in, line)) break;
        line_counter++;

        std::string trimmed_line = trim(line);

        if (buffer.empty() && !trimmed_line.empty() && trimmed_line[0] == '.') {
            process_dot_command(state, line);
            if (state.had_error && state.bail_on_error) break;
            continue;
        }

        if (buffer.empty()) stmt_start_line = line_counter;

        buffer += line + "\n";

        if (sqlite3_complete(buffer.c_str())) {
            execute_sql(state, buffer, stream_name, stmt_start_line);
            buffer.clear();
            if (state.had_error && state.bail_on_error) break;
        }
    }

    if (!buffer.empty() && !trim(buffer).empty()) {
        execute_sql(state, buffer, stream_name, stmt_start_line);
    }
}

