static void do_dump(ShellState &state, const std::string &pattern = "") {
    FILE *out = state.once_file ? state.once_file : state.out_file;
    fputs("PRAGMA foreign_keys=OFF;\nBEGIN TRANSACTION;\n", out);

    std::string sql = "SELECT name, type, sql FROM sqlite_schema WHERE sql IS NOT NULL AND type != 'meta'";
    if (!pattern.empty()) {
        sql += " AND (name LIKE '" + pattern + "' OR tbl_name LIKE '" + pattern + "')";
    }
    sql += " ORDER BY rowid ASC";

    sqlite3_stmt *stmt = nullptr;
    if (sqlite3_prepare_v2(state.db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            const char *name = (const char *)sqlite3_column_text(stmt, 0);
            const char *type = (const char *)sqlite3_column_text(stmt, 1);
            const char *create_sql = (const char *)sqlite3_column_text(stmt, 2);

            if (!name || !type || !create_sql) continue;

            if (strcmp(type, "table") == 0) {
                fprintf(out, "%s;\n", create_sql);
                std::string dump_data_sql = "SELECT * FROM \"" + std::string(name) + "\"";
                sqlite3_stmt *data_stmt = nullptr;
                if (sqlite3_prepare_v2(state.db, dump_data_sql.c_str(), -1, &data_stmt, nullptr) == SQLITE_OK) {
                    int ncols = sqlite3_column_count(data_stmt);
                    while (sqlite3_step(data_stmt) == SQLITE_ROW) {
                        fprintf(out, "INSERT INTO %s VALUES(", name);
                        for (int col = 0; col < ncols; ++col) {
                            if (col > 0) fputc(',', out);
                            fputs(quote_sql_literal(data_stmt, col).c_str(), out);
                        }
                        fputs(");\n", out);
                    }
                    sqlite3_finalize(data_stmt);
                }
            } else {
                fprintf(out, "%s;\n", create_sql);
            }
        }
        sqlite3_finalize(stmt);
    }

    fputs("COMMIT;\n", out);
}

static void do_import(ShellState &state, const std::vector<std::string> &args) {
    if (args.size() < 3) {
        std::cerr << "Usage: .import FILE TABLE\n";
        state.had_error = true;
        return;
    }
    bool is_csv = (state.mode == "csv");
    int skip_lines = 0;
    size_t idx = 1;

    while (idx < args.size() - 2) {
        if (args[idx] == "--csv") { is_csv = true; idx++; }
        else if (args[idx] == "--ascii") { is_csv = false; idx++; }
        else if (args[idx] == "-skip" && idx + 1 < args.size() - 2) {
            skip_lines = std::atoi(args[idx + 1].c_str());
            idx += 2;
        } else break;
    }

    std::string file_path = args[idx];
    std::string table_name = args[idx + 1];

    std::ifstream file(file_path);
    if (!file.is_open()) {
        std::cerr << "Error: cannot open \"" << file_path << "\"\n";
        state.had_error = true;
        return;
    }

    std::string line;
    for (int i = 0; i < skip_lines; ++i) {
        if (!std::getline(file, line)) return;
    }

    bool table_exists = false;
    std::string chk_sql = "SELECT 1 FROM sqlite_schema WHERE type='table' AND name='" + table_name + "'";
    sqlite3_stmt *chk_stmt = nullptr;
    if (sqlite3_prepare_v2(state.db, chk_sql.c_str(), -1, &chk_stmt, nullptr) == SQLITE_OK) {
        if (sqlite3_step(chk_stmt) == SQLITE_ROW) table_exists = true;
        sqlite3_finalize(chk_stmt);
    }

    auto parse_csv_line = [](const std::string &l, char sep) -> std::vector<std::string> {
        std::vector<std::string> fields;
        std::string current;
        bool in_quotes = false;
        for (size_t i = 0; i < l.size(); ++i) {
            char c = l[i];
            if (c == '"') {
                if (in_quotes && i + 1 < l.size() && l[i + 1] == '"') {
                    current += '"';
                    i++;
                } else {
                    in_quotes = !in_quotes;
                }
            } else if (c == sep && !in_quotes) {
                fields.push_back(current);
                current.clear();
            } else {
                current += c;
            }
        }
        fields.push_back(current);
        return fields;
    };

    char sep = is_csv ? ',' : (state.col_separator.empty() ? '|' : state.col_separator[0]);

    if (!table_exists) {
        if (!std::getline(file, line)) return;
        auto headers = parse_csv_line(line, sep);
        std::string create_sql = "CREATE TABLE \"" + table_name + "\" (";
        for (size_t i = 0; i < headers.size(); ++i) {
            if (i > 0) create_sql += ", ";
            create_sql += "\"" + headers[i] + "\" TEXT";
        }
        create_sql += ")";
        sqlite3_exec(state.db, create_sql.c_str(), nullptr, nullptr, nullptr);
    }

    execute_sql(state, "BEGIN TRANSACTION;", "import");
    while (std::getline(file, line)) {
        if (line.empty()) continue;
        auto fields = parse_csv_line(line, sep);
        std::string insert_sql = "INSERT INTO \"" + table_name + "\" VALUES(";
        for (size_t i = 0; i < fields.size(); ++i) {
            if (i > 0) insert_sql += ",";
            char *q = sqlite3_mprintf("%Q", fields[i].c_str());
            insert_sql += q;
            sqlite3_free(q);
        }
        insert_sql += ");";
        sqlite3_exec(state.db, insert_sql.c_str(), nullptr, nullptr, nullptr);
    }
    execute_sql(state, "COMMIT;", "import");
}

static void process_dot_command(ShellState &state, const std::string &line) {
    auto args = parse_args(line);
    if (args.empty()) return;

    std::string cmd = args[0];
    if (cmd[0] == '.') cmd = cmd.substr(1);

    if (cmd == "exit" || cmd == "quit") {
        int code = 0;
        if (args.size() > 1) code = std::atoi(args[1].c_str());
        exit(code);
    } else if (cmd == "help") {
        std::string pat = (args.size() > 1) ? args[1] : "";
        print_help(pat);
    } else if (cmd == "headers") {
        if (args.size() < 2) {
            std::cerr << "Usage: .headers on|off\n";
            state.had_error = true;
        } else {
            state.show_headers = (args[1] == "on" || args[1] == "1" || args[1] == "yes");
        }
    } else if (cmd == "bail") {
        if (args.size() < 2) {
            std::cerr << "Usage: .bail on|off\n";
            state.had_error = true;
        } else {
            state.bail_on_error = (args[1] == "on" || args[1] == "1" || args[1] == "yes");
        }
    } else if (cmd == "echo") {
        if (args.size() < 2) {
            std::cerr << "Usage: .echo on|off\n";
            state.had_error = true;
        } else {
            state.echo_commands = (args[1] == "on" || args[1] == "1" || args[1] == "yes");
        }
    } else if (cmd == "changes") {
        if (args.size() < 2) {
            std::cerr << "Usage: .changes on|off\n";
            state.had_error = true;
        } else {
            state.show_changes = (args[1] == "on" || args[1] == "1" || args[1] == "yes");
        }
    } else if (cmd == "timer") {
        if (args.size() < 2) {
            std::cerr << "Usage: .timer on|off|once\n";
            state.had_error = true;
        } else {
            state.show_timer = (args[1] == "on" || args[1] == "1" || args[1] == "yes");
        }
    } else if (cmd == "nullvalue") {
        if (args.size() < 2) {
            std::cerr << "Usage: .nullvalue STRING\n";
            state.had_error = true;
        } else {
            state.null_value = args[1];
        }
    } else if (cmd == "separator") {
        if (args.size() < 2) {
            std::cerr << "Usage: .separator COL ?ROW?\n";
            state.had_error = true;
        } else {
            state.col_separator = args[1];
            if (args.size() > 2) state.row_separator = args[2];
        }
    } else if (cmd == "newline") {
        if (args.size() > 1) state.row_separator = args[1];
    } else if (cmd == "mode") {
        if (args.size() < 2) {
            printf(".mode %s\n", state.mode.c_str());
        } else {
            std::string m = args[1];
            static const char *modes[] = {"ascii", "box", "column", "csv", "html", "json", "line", "list", "markdown", "quote", "table", "tabs", nullptr};
            bool valid = false;
            for (int i = 0; modes[i]; ++i) {
                if (m == modes[i]) { valid = true; break; }
            }
            if (valid) {
                state.mode = m;
            } else {
                std::cerr << "argv[2]: .mode " << m << "\n"
                          << "argv[2]:       ^--- unknown mode\n"
                          << "argv[2]: Use \".help .mode\" for more info\n";
                state.had_error = true;
            }
        }
    } else if (cmd == "tables") {
        std::string sql = "SELECT name FROM sqlite_schema WHERE type IN ('table', 'view') AND name NOT LIKE 'sqlite_%'";
        if (args.size() > 1) {
            sql += " AND name LIKE '" + args[1] + "'";
        }
        sql += " ORDER BY name";

        sqlite3_stmt *stmt = nullptr;
        if (sqlite3_prepare_v2(state.db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
            std::vector<std::string> names;
            while (sqlite3_step(stmt) == SQLITE_ROW) {
                const char *n = (const char *)sqlite3_column_text(stmt, 0);
                if (n) names.push_back(n);
            }
            sqlite3_finalize(stmt);
            FILE *out = state.once_file ? state.once_file : state.out_file;
            for (size_t i = 0; i < names.size(); ++i) {
                fprintf(out, "%s%s", names[i].c_str(), (i + 1 == names.size() || (i + 1) % 3 == 0) ? "\n" : "     ");
            }
            if (!names.empty() && names.size() % 3 != 0) fprintf(out, "\n");
        }
    } else if (cmd == "schema") {
        std::string sql = "SELECT sql FROM sqlite_schema WHERE sql IS NOT NULL AND type != 'meta'";
        if (args.size() > 1) {
            sql += " AND (name LIKE '" + args[1] + "' OR tbl_name LIKE '" + args[1] + "')";
        }
        sql += " ORDER BY rowid";

        sqlite3_stmt *stmt = nullptr;
        if (sqlite3_prepare_v2(state.db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
            FILE *out = state.once_file ? state.once_file : state.out_file;
            while (sqlite3_step(stmt) == SQLITE_ROW) {
                const char *s = (const char *)sqlite3_column_text(stmt, 0);
                if (s) fprintf(out, "%s;\n", s);
            }
            sqlite3_finalize(stmt);
        }
    } else if (cmd == "indexes") {
        std::string sql = "SELECT name FROM sqlite_schema WHERE type = 'index'";
        if (args.size() > 1) {
            sql += " AND name LIKE '" + args[1] + "'";
        }
        sql += " ORDER BY name";

        sqlite3_stmt *stmt = nullptr;
        if (sqlite3_prepare_v2(state.db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
            FILE *out = state.once_file ? state.once_file : state.out_file;
            while (sqlite3_step(stmt) == SQLITE_ROW) {
                const char *n = (const char *)sqlite3_column_text(stmt, 0);
                if (n) fprintf(out, "%s\n", n);
            }
            sqlite3_finalize(stmt);
        }
    } else if (cmd == "databases") {
        FILE *out = state.once_file ? state.once_file : state.out_file;
        const char *db_path = sqlite3_db_filename(state.db, "main");
        if (!db_path || state.db_filename == ":memory:" || state.db_filename.empty()) {
            fprintf(out, "main: \"\" r/w\n");
        } else {
            char abs_buf[PATH_MAX];
            if (realpath(db_path, abs_buf)) {
                fprintf(out, "main: %s r/w\n", abs_buf);
            } else {
                fprintf(out, "main: %s r/w\n", db_path);
            }
        }
    } else if (cmd == "dump") {
        std::string pat = (args.size() > 1) ? args[1] : "";
        do_dump(state, pat);
    } else if (cmd == "import") {
        do_import(state, args);
    } else if (cmd == "read") {
        if (args.size() < 2) {
            std::cerr << "Usage: .read FILE\n";
            state.had_error = true;
            return;
        }
        std::string file_path = args[1];
        if (!file_path.empty() && file_path[0] == '|') {
            std::string pipe_cmd = file_path.substr(1);
            FILE *p = popen(pipe_cmd.c_str(), "r");
            if (p) {
                char buf[4096];
                std::string input;
                while (fgets(buf, sizeof(buf), p)) input += buf;
                pclose(p);
                std::istringstream iss(input);
                read_and_process_stream(state, iss, false, pipe_cmd);
            }
        } else {
            std::ifstream file(file_path);
            if (!file.is_open()) {
                std::cerr << "Error: cannot open \"" << file_path << "\"\n";
                state.had_error = true;
                return;
            }
            read_and_process_stream(state, file, false, file_path);
        }
    } else if (cmd == "output") {
        if (state.out_is_pipe && state.out_file) {
            pclose(state.out_file);
            state.out_file = stdout;
            state.out_is_pipe = false;
        } else if (state.out_file && state.out_file != stdout) {
            fclose(state.out_file);
            state.out_file = stdout;
        }

        if (args.size() > 1 && args[1] != "stdout") {
            std::string dest = args[1];
            if (!dest.empty() && dest[0] == '|') {
                state.out_file = popen(dest.substr(1).c_str(), "w");
                state.out_is_pipe = true;
            } else {
                state.out_file = fopen(dest.c_str(), "w");
                state.out_is_pipe = false;
            }
            if (!state.out_file) state.out_file = stdout;
        }
    } else if (cmd == "once") {
        if (args.size() > 1) {
            std::string dest = args[1];
            if (!dest.empty() && dest[0] == '|') {
                state.once_file = popen(dest.substr(1).c_str(), "w");
                state.once_is_pipe = true;
            } else {
                state.once_file = fopen(dest.c_str(), "w");
                state.once_is_pipe = false;
            }
        }
    } else if (cmd == "backup" || cmd == "save") {
        if (args.size() < 2) {
            std::cerr << "Usage: .backup ?DB? FILE\n";
            state.had_error = true;
            return;
        }
        std::string dest_file = (args.size() > 2) ? args[2] : args[1];
        sqlite3 *dest_db = nullptr;
        if (sqlite3_open(dest_file.c_str(), &dest_db) == SQLITE_OK) {
