static const char *SQLITE_SHELL_VERSION = "3.54.0 2026-04-14 20:02:49 49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b (64-bit)";
static const char *SQLITE_SHELL_VER_SHORT = "3.54.0 2026-04-14 20:02:49 49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b";

struct ShellState {
    sqlite3 *db = nullptr;
    std::string db_filename = ":memory:";
    bool interactive = false;
    bool bail_on_error = false;
    bool echo_commands = false;
    bool show_headers = false;
    bool show_changes = false;
    bool show_timer = false;
    std::string null_value = "";
    std::string col_separator = "|";
    std::string row_separator = "\n";
    std::string main_prompt = "";
    std::string continue_prompt = "   ...> ";
