    FILE *once_file = nullptr;
    bool once_is_pipe = false;
    bool had_error = false;
    std::string argv0 = "./executable";
    int current_line_number = 1;
};

// Helper: Trim leading and trailing whitespace
static std::string trim(const std::string &s) {
    size_t start = s.find_first_not_of(" \t\r\n");
    if (start == std::string::npos) return "";
    size_t end = s.find_last_not_of(" \t\r\n");
    return s.substr(start, end - start + 1);
}

// Helper: Get basename of path
static std::string get_basename(const std::string &path) {
    if (path.empty() || path == ":memory:") return "in-memory";
    size_t pos = path.find_last_of("/\\");
    if (pos != std::string::npos) return path.substr(pos + 1);
    return path;
}

// Helper: Parse command line style arguments (supporting quotes)
static std::vector<std::string> parse_args(const std::string &line) {
    std::vector<std::string> args;
    std::string current;
    bool in_sq = false, in_dq = false;
    bool escape = false;

    for (size_t i = 0; i < line.size(); ++i) {
        char c = line[i];
        if (escape) {
            current += c;
            escape = false;
            continue;
        }
        if (c == '\\' && (in_sq || in_dq)) {
            escape = true;
            continue;
        }
        if (c == '\'' && !in_dq) {
            in_sq = !in_sq;
            continue;
        }
        if (c == '"' && !in_sq) {
            in_dq = !in_dq;
            continue;
        }
        if (std::isspace((unsigned char)c) && !in_sq && !in_dq) {
            if (!current.empty()) {
                args.push_back(current);
                current.clear();
            }
            continue;
        }
        current += c;
    }
    if (!current.empty()) {
        args.push_back(current);
    }
    return args;
}

static bool open_database(ShellState &state, const std::string &filename, bool readonly = false, bool ifexists = false) {
    if (state.db) {
        sqlite3_close(state.db);
        state.db = nullptr;
    }
    state.db_filename = filename;
    int flags = SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE;
    if (readonly) {
        flags = SQLITE_OPEN_READONLY;
    }
    if (ifexists) {
        flags = SQLITE_OPEN_READWRITE;
    }

    const char *db_path = filename.empty() ? ":memory:" : filename.c_str();
    int rc = sqlite3_open_v2(db_path, &state.db, flags, nullptr);
    if (rc != SQLITE_OK) {
        std::cerr << "Error: unable to open database \"" << db_path << "\": " 
                  << (state.db ? sqlite3_errmsg(state.db) : "unable to open database file") << "\n";
        if (state.db) {
            sqlite3_close(state.db);
            state.db = nullptr;
        }
        state.had_error = true;
        return false;
    }
    return true;
}

// HTML Escaping
static std::string escape_html(const std::string &s) {
    std::string res;
    for (char c : s) {
        switch (c) {
            case '<': res += "&lt;"; break;
            case '>': res += "&gt;"; break;
            case '&': res += "&amp;"; break;
            case '"': res += "&quot;"; break;
            case '\'': res += "&#39;"; break;
            default: res += c; break;
        }
    }
    return res;
}

// JSON Escaping
static std::string escape_json(const std::string &s) {
    std::string res;
    for (char c : s) {
        switch (c) {
            case '"': res += "\\\""; break;
            case '\\': res += "\\\\"; break;
            case '\b': res += "\\b"; break;
            case '\f': res += "\\f"; break;
            case '\n': res += "\\n"; break;
            case '\r': res += "\\r"; break;
            case '\t': res += "\\t"; break;
            default:
                if ((unsigned char)c < 0x20) {
                    char buf[10];
                    snprintf(buf, sizeof(buf), "\\u%04x", (unsigned char)c);
                    res += buf;
                } else {
                    res += c;
                }
                break;
        }
    }
    return res;
}

// CSV / Tabs Quoting
static std::string quote_csv(const std::string &s, char sep = ',') {
    bool need_quote = false;
    if (s.find(sep) != std::string::npos || s.find('"') != std::string::npos || 
        s.find('\n') != std::string::npos || s.find('\r') != std::string::npos) {
        need_quote = true;
    }
    if (!need_quote) return s;
    std::string res = "\"";
    for (char c : s) {
        if (c == '"') res += "\"\"";
        else res += c;
    }
    res += "\"";
    return res;
}

// Quote Mode SQL literal formatting
static std::string quote_sql_literal(sqlite3_stmt *stmt, int col) {
    int type = sqlite3_column_type(stmt, col);
    if (type == SQLITE_NULL) return "NULL";
    if (type == SQLITE_INTEGER) return std::to_string(sqlite3_column_int64(stmt, col));
    if (type == SQLITE_FLOAT) {
        std::ostringstream ss;
        ss << sqlite3_column_double(stmt, col);
        return ss.str();
    }
    if (type == SQLITE_BLOB) {
        const unsigned char *blob = (const unsigned char *)sqlite3_column_blob(stmt, col);
        int bytes = sqlite3_column_bytes(stmt, col);
        std::string res = "x'";
        static const char hex[] = "0123456789abcdef";
        for (int i = 0; i < bytes; ++i) {
            res += hex[(blob[i] >> 4) & 0x0F];
            res += hex[blob[i] & 0x0F];
        }
        res += "'";
        return res;
    }
    // TEXT
    const char *text = (const char *)sqlite3_column_text(stmt, col);
    if (!text) return "NULL";
    std::string str(text);
    bool has_control = false;
    for (char c : str) {
        if ((unsigned char)c < 0x20 || c == 0x7F) {
            has_control = true;
            break;
        }
    }
    if (has_control && str.find('\t') != std::string::npos && str.find('\n') == std::string::npos) {
        std::string res = "unistr('";
        for (char c : str) {
            if (c == '\'') res += "''";
            else if ((unsigned char)c < 0x20) {
                char buf[10];
                snprintf(buf, sizeof(buf), "\\u%04x", (unsigned char)c);
                res += buf;
            } else res += c;
        }
        res += "')";
        return res;
    }
    std::string res = "'";
    for (char c : str) {
        if (c == '\'') res += "''";
        else res += c;
    }
    res += "'";
    return res;
}

static void render_results(ShellState &state, sqlite3_stmt *stmt, FILE *out) {
    int col_count = sqlite3_column_count(stmt);
    if (col_count == 0) return;

    std::vector<std::string> headers(col_count);

    for (int i = 0; i < col_count; ++i) {
        const char *name = sqlite3_column_name(stmt, i);
        headers[i] = name ? name : "";
    }

    if (state.mode == "json") {
        fprintf(out, "[");
        bool first_row = true;
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            if (!first_row) fprintf(out, ",\n");
            first_row = false;
            fprintf(out, "{");
            for (int i = 0; i < col_count; ++i) {
                if (i > 0) fprintf(out, ",");
                fprintf(out, "\"%s\":", escape_json(headers[i]).c_str());
                int type = sqlite3_column_type(stmt, i);
                if (type == SQLITE_NULL) {
                    fprintf(out, "null");
                } else if (type == SQLITE_INTEGER) {
                    fprintf(out, "%lld", (long long)sqlite3_column_int64(stmt, i));
                } else if (type == SQLITE_FLOAT) {
                    fprintf(out, "%g", sqlite3_column_double(stmt, i));
                } else {
                    const char *val = (const char *)sqlite3_column_text(stmt, i);
                    fprintf(out, "\"%s\"", escape_json(val ? val : "").c_str());
                }
            }
            fprintf(out, "}");
        }
        fprintf(out, "]\n");
        return;
    }

    if (state.mode == "list") {
        if (state.show_headers) {
            for (int i = 0; i < col_count; ++i) {
                if (i > 0) fputs(state.col_separator.c_str(), out);
                fputs(headers[i].c_str(), out);
            }
            fputs(state.row_separator.c_str(), out);
        }
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            for (int i = 0; i < col_count; ++i) {
                if (i > 0) fputs(state.col_separator.c_str(), out);
                if (sqlite3_column_type(stmt, i) == SQLITE_NULL) {
                    fputs(state.null_value.c_str(), out);
                } else {
                    const char *val = (const char *)sqlite3_column_text(stmt, i);
                    fputs(val ? val : "", out);
                }
            }
            fputs(state.row_separator.c_str(), out);
        }
        return;
    }

    if (state.mode == "csv" || state.mode == "tabs") {
        char sep = (state.mode == "csv") ? ',' : '\t';
        if (state.show_headers) {
            for (int i = 0; i < col_count; ++i) {
                if (i > 0) fputc(sep, out);
                fputs(quote_csv(headers[i], sep).c_str(), out);
            }
            fputs("\n", out);
        }
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            for (int i = 0; i < col_count; ++i) {
                if (i > 0) fputc(sep, out);
                if (sqlite3_column_type(stmt, i) == SQLITE_NULL) {
                    fputs(state.null_value.c_str(), out);
                } else {
                    const char *val = (const char *)sqlite3_column_text(stmt, i);
                    fputs(quote_csv(val ? val : "", sep).c_str(), out);
                }
            }
            fputs("\n", out);
        }
        return;
    }

    if (state.mode == "html") {
        if (state.show_headers) {
            fputs("<TR>\n", out);
            for (int i = 0; i < col_count; ++i) {
                fprintf(out, "<TH>%s\n", escape_html(headers[i]).c_str());
            }
            fputs("</TR>\n", out);
        }
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            fputs("<TR>\n", out);
            for (int i = 0; i < col_count; ++i) {
                if (sqlite3_column_type(stmt, i) == SQLITE_NULL) {
                    if (!state.null_value.empty()) {
                        fprintf(out, "<TD>%s\n", escape_html(state.null_value).c_str());
                    } else {
                        fputs("<TD>null\n", out);
                    }
                } else {
                    const char *val = (const char *)sqlite3_column_text(stmt, i);
                    fprintf(out, "<TD>%s\n", escape_html(val ? val : "").c_str());
                }
            }
            fputs("</TR>\n", out);
        }
        return;
    }

    if (state.mode == "quote") {
        if (state.show_headers) {
            for (int i = 0; i < col_count; ++i) {
                if (i > 0) fputc(',', out);
                fprintf(out, "'%s'", headers[i].c_str());
            }
            fputs("\n", out);
        }
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            for (int i = 0; i < col_count; ++i) {
                if (i > 0) fputc(',', out);
                fputs(quote_sql_literal(stmt, i).c_str(), out);
            }
            fputs("\n", out);
        }
        return;
    }

    if (state.mode == "ascii") {
        if (state.show_headers) {
            for (int i = 0; i < col_count; ++i) {
                fputs(headers[i].c_str(), out);
                fputc('\x1f', out);
            }
            fputc('\x1e', out);
        }
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            for (int i = 0; i < col_count; ++i) {
                if (sqlite3_column_type(stmt, i) == SQLITE_NULL) {
                    fputs(state.null_value.c_str(), out);
                } else {
                    const char *val = (const char *)sqlite3_column_text(stmt, i);
                    fputs(val ? val : "", out);
                }
                fputc('\x1f', out);
            }
            fputc('\x1e', out);
        }
        return;
    }

    if (state.mode == "line") {
        size_t max_hdr_len = 0;
        for (const auto &h : headers) {
            if (h.length() > max_hdr_len) max_hdr_len = h.length();
        }
        bool first = true;
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            if (!first) fputs("\n", out);
            first = false;
            for (int i = 0; i < col_count; ++i) {
                std::string val_str;
                if (sqlite3_column_type(stmt, i) == SQLITE_NULL) {
                    val_str = state.null_value;
                } else {
                    const char *v = (const char *)sqlite3_column_text(stmt, i);
                    val_str = v ? v : "";
                }
                fprintf(out, "%*s: %s\n", (int)max_hdr_len, headers[i].c_str(), val_str.c_str());
            }
        }
        return;
    }

    // Buffered modes: column, markdown, table, box
    std::vector<std::vector<std::string>> data;
    std::vector<bool> is_numeric(col_count, true);

    while (sqlite3_step(stmt) == SQLITE_ROW) {
        std::vector<std::string> row(col_count);
        for (int i = 0; i < col_count; ++i) {
            int type = sqlite3_column_type(stmt, i);
            if (type == SQLITE_NULL) {
                row[i] = state.null_value;
            } else {
                const char *v = (const char *)sqlite3_column_text(stmt, i);
                row[i] = v ? v : "";
                if (type != SQLITE_INTEGER && type != SQLITE_FLOAT) {
                    is_numeric[i] = false;
                }
            }
        }
        data.push_back(row);
    }

    std::vector<size_t> widths(col_count, 0);
    for (int i = 0; i < col_count; ++i) {
        widths[i] = headers[i].length();
        for (const auto &row : data) {
            if (row[i].length() > widths[i]) widths[i] = row[i].length();
        }
    }

    if (state.mode == "column") {
        if (state.show_headers) {
            for (int i = 0; i < col_count; ++i) {
                if (i > 0) fputs("  ", out);
                if (is_numeric[i]) {
                    fprintf(out, "%*s", (int)widths[i], headers[i].c_str());
                } else {
                    fprintf(out, "%-*s", (int)widths[i], headers[i].c_str());
                }
            }
            fputs("\n", out);
            for (int i = 0; i < col_count; ++i) {
                if (i > 0) fputs("  ", out);
                std::string dash(widths[i], '-');
                fputs(dash.c_str(), out);
            }
            fputs("\n", out);
        }
        for (const auto &row : data) {
            for (int i = 0; i < col_count; ++i) {
                if (i > 0) fputs("  ", out);
                if (is_numeric[i]) {
                    fprintf(out, "%*s", (int)widths[i], row[i].c_str());
                } else {
                    fprintf(out, "%-*s", (int)widths[i], row[i].c_str());
                }
            }
            fputs("\n", out);
        }
        return;
    }

    auto center_str = [](const std::string &s, size_t w) -> std::string {
        if (s.length() >= w) return s;
        size_t left = (w - s.length()) / 2;
        size_t right = w - s.length() - left;
        return std::string(left, ' ') + s + std::string(right, ' ');
    };

    if (state.mode == "markdown") {
        // Header
        fputs("|", out);
        for (int i = 0; i < col_count; ++i) {
            fprintf(out, " %s |", center_str(headers[i], widths[i]).c_str());
        }
        fputs("\n|", out);
        for (int i = 0; i < col_count; ++i) {
            std::string dash(widths[i] + 2, '-');
            fprintf(out, "%s|", dash.c_str());
        }
        fputs("\n", out);
        for (const auto &row : data) {
            fputs("|", out);
            for (int i = 0; i < col_count; ++i) {
                if (is_numeric[i]) {
                    fprintf(out, " %*s |", (int)widths[i], row[i].c_str());
                } else {
                    fprintf(out, " %-*s |", (int)widths[i], row[i].c_str());
                }
            }
            fputs("\n", out);
        }
        return;
    }

    if (state.mode == "table") {
        // Top line
        fputs("+", out);
        for (int i = 0; i < col_count; ++i) {
            std::string dash(widths[i] + 2, '-');
            fprintf(out, "%s+", dash.c_str());
        }
        fputs("\n", out);

        if (state.show_headers) {
            fputs("|", out);
            for (int i = 0; i < col_count; ++i) {
                fprintf(out, " %s |", center_str(headers[i], widths[i]).c_str());
            }
            fputs("\n+", out);
            for (int i = 0; i < col_count; ++i) {
                std::string dash(widths[i] + 2, '-');
                fprintf(out, "%s+", dash.c_str());
            }
            fputs("\n", out);
        }

        for (const auto &row : data) {
            fputs("|", out);
            for (int i = 0; i < col_count; ++i) {
                if (is_numeric[i]) {
                    fprintf(out, " %*s |", (int)widths[i], row[i].c_str());
                } else {
                    fprintf(out, " %-*s |", (int)widths[i], row[i].c_str());
                }
            }
            fputs("\n", out);
        }

        // Bottom line
        fputs("+", out);
        for (int i = 0; i < col_count; ++i) {
            std::string dash(widths[i] + 2, '-');
            fprintf(out, "%s+", dash.c_str());
        }
        fputs("\n", out);
        return;
    }

    if (state.mode == "box") {
        // Top line
        fputs("╭", out);
        for (int i = 0; i < col_count; ++i) {
            for (size_t k = 0; k < widths[i] + 2; ++k) fputs("─", out);
            fputs(i == col_count - 1 ? "╮" : "┬", out);
        }
        fputs("\n", out);

        if (state.show_headers) {
            fputs("│", out);
            for (int i = 0; i < col_count; ++i) {
                fprintf(out, " %s │", center_str(headers[i], widths[i]).c_str());
            }
            fputs("\n╞", out);
            for (int i = 0; i < col_count; ++i) {
                for (size_t k = 0; k < widths[i] + 2; ++k) fputs("═", out);
                fputs(i == col_count - 1 ? "╡" : "╪", out);
            }
            fputs("\n", out);
        }

        for (const auto &row : data) {
            fputs("│", out);
            for (int i = 0; i < col_count; ++i) {
                if (is_numeric[i]) {
                    fprintf(out, " %*s │", (int)widths[i], row[i].c_str());
                } else {
                    fprintf(out, " %-*s │", (int)widths[i], row[i].c_str());
                }
            }
            fputs("\n", out);
        }

        // Bottom line
        fputs("╰", out);
        for (int i = 0; i < col_count; ++i) {
            for (size_t k = 0; k < widths[i] + 2; ++k) fputs("─", out);
            fputs(i == col_count - 1 ? "╯" : "┴", out);
        }
        fputs("\n", out);
        return;
    }
}

