                       "   -init FILENAME       read/process named file\n"
                       "   -[no]header          turn headers on or off\n"
                       "   -help                show this message\n"
                       "   -html                set output mode to HTML\n"
                       "   -ifexists            only open if database already exists\n"
                       "   -interactive         force interactive I/O\n"
                       "   -json                set output mode to 'json'\n"
                       "   -line                set output mode to 'line'\n"
                       "   -list                set output mode to 'list'\n"
                       "   -lookaside SIZE N    use N entries of SZ bytes for lookaside memory\n"
                       "   -markdown            set output mode to 'markdown'\n"
                       "   -maxsize N           maximum size for a --deserialize database\n"
                       "   -memtrace            trace all memory allocations and deallocations\n"
                       "   -mmap N              default mmap size set to N\n"
                       "   -newline SEP         set output row separator. Default: '\\n'\n"
                       "   -nofollow            refuse to open symbolic links to database files\n"
                       "   -noinit              Do not read the ~/.sqliterc file at startup\n"
                       "   -nonce STRING        set the safe-mode escape nonce\n"
                       "   -no-rowid-in-view    Disable rowid-in-view using sqlite3_config()\n"
                       "   -nullvalue TEXT      set text string for NULL values. Default ''\n"
                       "   -pagecache SIZE N    use N slots of SZ bytes each for page cache memory\n"
                       "   -pcachetrace         trace all page cache operations\n"
                       "   -quote               set output mode to 'quote'\n"
                       "   -readonly            open the database read-only\n"
                       "   -safe                enable safe-mode\n"
                       "   -screenwidth N       use N as the default screenwidth \n"
                       "   -separator SEP       set output column separator. Default: '|'\n"
                       "   -stats               print memory stats before each finalize\n"
                       "   -table               set output mode to 'table'\n"
                       "   -tabs                set output mode to 'tabs'\n"
                       "   -unsafe-testing      allow unsafe commands and modes for testing\n"
                       "   -version             show SQLite version\n"
                       "   -vfs NAME            use NAME as the default VFS\n"
                       "   -vfstrace            enable tracing of all VFS calls\n"
                       "   -zip                 open the file as a ZIP Archive\n", argv[0]);
                return 0;
            } else if (arg == "-bail") {
                state.bail_on_error = true;
            } else if (arg == "-batch") {
                explicit_batch = true;
            } else if (arg == "-interactive") {
                explicit_interactive = true;
            } else if (arg == "-echo") {
                state.echo_commands = true;
            } else if (arg == "-header" || arg == "-headers") {
                state.show_headers = true;
            } else if (arg == "-noheader" || arg == "-noheaders") {
                state.show_headers = false;
            } else if (arg == "-readonly") {
                readonly = true;
            } else if (arg == "-ifexists") {
                ifexists = true;
            } else if (arg == "-noinit") {
                read_init = false;
            } else if (arg == "-cmd") {
                if (i + 1 < argc) {
                    cmd_queue.push_back(argv[++i]);
                }
            } else if (arg == "-init") {
                if (i + 1 < argc) {
                    init_files.push_back(argv[++i]);
                }
            } else if (arg == "-nullvalue") {
                if (i + 1 < argc) {
                    state.null_value = argv[++i];
                }
            } else if (arg == "-separator") {
                if (i + 1 < argc) {
                    state.col_separator = argv[++i];
                }
            } else if (arg == "-newline") {
                if (i + 1 < argc) {
                    state.row_separator = argv[++i];
                }
            } else if (arg == "-ascii") state.mode = "ascii";
            else if (arg == "-box") state.mode = "box";
            else if (arg == "-column") state.mode = "column";
            else if (arg == "-csv") state.mode = "csv";
            else if (arg == "-html") state.mode = "html";
            else if (arg == "-json") state.mode = "json";
            else if (arg == "-line") state.mode = "line";
            else if (arg == "-list") state.mode = "list";
            else if (arg == "-markdown") state.mode = "markdown";
            else if (arg == "-quote") state.mode = "quote";
            else if (arg == "-table") state.mode = "table";
            else if (arg == "-tabs") state.mode = "tabs";
            else {
                std::cerr << argv[0] << ": Error: unknown option: " << arg << "\n"
                          << "Use -help for a list of options.\n";
                return 1;
            }
        } else {
            positional_args.push_back(arg);
        }
        i++;
    }

    std::vector<std::string> sql_args;
    if (!positional_args.empty()) {
        db_file = positional_args[0];
        for (size_t k = 1; k < positional_args.size(); ++k) {
            sql_args.push_back(positional_args[k]);
        }
    }

    if (!open_database(state, db_file, readonly, ifexists)) {
        return 1;
    }

    for (const auto &f : init_files) {
        std::ifstream file(f);
        if (file.is_open()) {
            read_and_process_stream(state, file, false, f);
        }
    }

    for (const auto &c : cmd_queue) {
        if (!c.empty() && c[0] == '.') {
            process_dot_command(state, c);
        } else {
            execute_sql(state, c, "3rd command line argument");
        }
        if (state.had_error && state.bail_on_error) return 1;
    }

    bool is_interactive = false;
    if (explicit_interactive) is_interactive = true;
    else if (explicit_batch) is_interactive = false;
    else if (sql_args.empty() && isatty(STDIN_FILENO)) is_interactive = true;

    if (!sql_args.empty()) {
        for (size_t k = 0; k < sql_args.size(); ++k) {
            std::string arg_desc;
            int arg_idx = 2 + (int)k;
            if (arg_idx == 2) arg_desc = "2nd command line argument";
            else if (arg_idx == 3) arg_desc = "3rd command line argument";
            else arg_desc = std::to_string(arg_idx) + "th command line argument";

            if (!sql_args[k].empty() && sql_args[k][0] == '.') {
                process_dot_command(state, sql_args[k]);
            } else {
                execute_sql(state, sql_args[k], arg_desc);
            }
            if (state.had_error && state.bail_on_error) return 1;
        }
    } else {
        read_and_process_stream(state, std::cin, is_interactive, "stdin");
    }

    return state.had_error ? 1 : 0;
}
EOF"}

